// Registering cross-platform configuration on globalThis:
UniversalConfigStore.set('institute', 'Coder & AccoTax');
UniversalConfigStore.set('center', 'Barrackpore Lab');
UniversalConfigStore.set('course', 'JS-PRO-101');

// Querying global settings:
UniversalConfigStore.get('institute');

// 1. Primitive value copying (Call Stack):
let originalScore = 95;
let copiedScore = originalScore;
copiedScore = 100;

// 2. Reference pointer copying (Memory Heap):
const originalStudent = { name: 'Swadeep', skills: ['HTML'] };
const studentReference = originalStudent;
studentReference.name = 'Swadeep Mukherjee';

// Generating dynamic student status card component:
createStudentBadge({
  id: 101,
  name: 'Swadeep Mukherjee',
  course: 'JS Foundations & Syntax Mastery'
});

// Toggling UI presentation state via JavaScript class management:
ThemeController.toggle(); // Flips to 'dark' mode
ThemeController.toggle(); // Flips back to 'light' mode

// 1. Executing query inside <head> before body exists:
const earlyElement = document.getElementById('app'); // null!

// 2. Executing query right before </body> tag:
const readyElement = document.getElementById('app'); // <div id='app'>

// Parameterized console diagnostic logging:
generateStudentDiagnostic(
  'Swadeep Mukherjee',
  101,
  98.75,
  { batch: 'Weekend Pro', center: 'Barrackpore' }
);

// Formatted dataset with column whitelisting:
const enrollments = [
  { studentId: 101, name: 'Swadeep', score: 98, status: 'Active' },
  { studentId: 102, name: 'Tuhina', score: 95, status: 'Active' }
];

console.table(enrollments, ['name', 'score', 'status']);

// Running performance micro-benchmarks:
console.time('string-concat-timer');
// ... execute 100,000 string concatenations
console.timeEnd('string-concat-timer');

// Tracking function execution count per label:
handleUserAction('login_click');
handleUserAction('login_click');

// Resetting specific counter:
console.countReset('Action: login_click');
handleUserAction('login_click');

// Triggering deep execution stack trace from nested calculation:
const cart = [
  { name: 'JS Handbook', price: 1000, discount: 0.1 },
  { name: 'VIP Pass', price: 5000, discount: 0.75 } // Triggers trace!
];

processCheckoutCart(cart);

// Enforcing strict mode inside function scope:
function runSafeModule() {
  'use strict';

  // Attempting undeclared assignment:
  unintentionalGlobal = 'This will throw ReferenceError!';
}

runSafeModule();

// Comparing 'this' binding in sloppy vs strict mode:
function getSloppyThis() { return this; }
function getStrictThis() { 'use strict'; return this; }

getSloppyThis(); // Returns window / global
getStrictThis(); // Returns undefined

// Enforcing object immutability under strict mode:
'use strict';

const config = Object.freeze({
  appName: 'CoderAccoTaxLMS',
  taxRate: 0.18
});

// Attempting property mutation:
config.taxRate = 0.25;

// Calculating student grade with JSDoc typing contract:
evaluateStudentGrade('Swadeep Mukherjee', 95, 100);
evaluateStudentGrade('Debangshu', 82, 100);

// Comparing ASI Line-Break Return vs Same-Line Return:
// Function 1: Broken return (ASI inserts semicolon after return keyword)
function getBroken() {
  return
  { student: 'Swadeep', score: 98 };
}

// Function 2: Correct same-line return
function getCorrect() {
  return { student: 'Swadeep', score: 98 };
}

// Demonstrating defensive semicolons in semicolon-free code:
const user = 'Swadeep'
;(function() {
  console.log('Defensive semicolon protects IIFE!');
})()

const a = 1, b = 2
;[a, b].forEach(val => console.log(val))
